import { atom, read, update } from 'claude-code'
import type { Elements, EngineInterface, Register, RenderElement, TextProps } from 'claude-code'

import type { RippleMap, RippleMapping, RippleMode, RippleNode, RippleOrigin, RippleScope } from '../types'
import {
  DEFAULT_BRANCH_COMMANDS,
  HASH_COMMAND,
  HEAD,
  UNTRACKED_COMMAND,
  describeChanges,
  diffCommand,
  hashCommands,
  hashInput,
  mergeBaseCommand,
  printsOf,
  readChanges,
  readRequest,
} from './changes'
import type { Base, Changes } from './changes'
import { COLORS, LEGEND, clipStart, locOf, markOf } from './draw'
import { editorCommands } from './editor'
import type { Move, Paint, Pan, Room } from './draw'
import { fileOf, filesOf, symbolIn } from './files'
import type { FileMap } from './files'
import { graphOf } from './graph'
import { drawList, listSays, scrollList, showInList, stepInList } from './list'
import {
  REPORT_DESCRIPTION,
  REPORT_SCHEMA,
  editedSince,
  flagged,
  headerText,
  movedText,
  originText,
  readReport,
  readStored,
  misnamedIn,
  statusText,
} from './map'
import {
  MAPPER_DESCRIPTION,
  MAPPER_NAME,
  MAPPER_PROMPT,
  MAPPER_TYPE,
  MAP_DESCRIPTION,
  MAP_NAME,
  MAP_SAYS,
  MAP_SCHEMA,
  MAP_TOOL,
  NO_ASKING,
  REPORT_SAYS,
  STOPPED,
  askPrompt,
  commandOf,
  describeCall,
  mapAnswer,
  mapperTools,
  misnamedReply,
  progressText,
  reportReply,
  taskPrompt,
} from './mapper'
import { treeView } from './tree'
import { LIST_MOVES, MOVES, factsOf, modeIn, nextFlagged, planOf, selectedOf } from './view'

const PANE = 'ripple'
/** A room tall enough to draw any map whole, which is how the rows a map needs are counted. */
const WHOLE_ROWS = 1000
const ORIGIN: Pan = { x: 0, y: 0 }
/** What the line over the list holds beside the path and the count: its mark, and a dot with its spaces. */
const OVER_LIST_CHARS = '▸ '.length + ' · '.length
/** The columns the pane asks for when it is docked beside the transcript, and the fewest it draws in. */
const PANE_COLUMNS = 76
const MIN_COLUMNS = 24
/** How long a git command may run, in milliseconds. */
const GIT_TIMEOUT_MS = 20_000
/** How long an editor's command may run before it is taken not to have opened the file, in milliseconds. */
const EDITOR_TIMEOUT_MS = 5_000
/** How soon a second click on a row of the tree or the list follows the first to open its file, in milliseconds. */
const DOUBLE_CLICK_MS = 400
/** The longest a call for a map waits for its mapper, in milliseconds. */
const MAP_WAIT_MS = 10 * 60_000
/** The longest one step of that wait is held, in milliseconds: well within a hook's own budget. */
const WAIT_STEP_MS = 3_000
/** The most rows the graph in the row of the map tool's answer takes. */
const TOOL_ROWS = 30
/** How many times a mapper's report is refused for naming symbols wrongly, before it is taken as it is. */
const NAME_CHECKS = 2
/** How many of the maps the map tool answered with are kept to draw in their rows: as many as graphlet keeps sites for. */
const ANSWERED_MAPS = 128
/** How many endings of mappings are kept for the calls that wait on them. */
const ENDINGS = 16
/** The states of an agent that is still at work. */
const AT_WORK: readonly string[] = ['pending', 'running', 'waiting']
/**
 * The keys that start something: a turn of the conversation, a mapper, and
 * the person's editor. They are digits, which the first letter of a typed
 * prompt never is.
 */
const ASK = '1'
const REMAP = '2'
const OPEN = '3'

/** The person's two answers when Claude asks Ripple for a mapping. */
const MAP_IT = 'Map them'
const NOT_NOW = 'Not now'

const NOT_A_REPOSITORY = 'Ripple: this is not a git repository, so there are no changes to map.'
const NO_DEFAULT_BRANCH =
  'Ripple: found no default branch to compare this one with (looked for origin/HEAD, main, and master). Run /ripple to map the uncommitted changes.'
const GIT_FAILED =
  'Ripple: git could not show the changes. A repository with no commits yet has nothing to compare them with.'

const map = atom({ plugin: 'ripple', key: 'map' } as const, null)
const mapping = atom({ plugin: 'ripple', key: 'mapping' } as const, null)
const view = atom({ plugin: 'ripple', key: 'view' } as const, { mode: null, selected: null, pan: null, top: null })

/** The view the map opens in until the person switches: the plugin's `view` option. */
let firstMode: RippleMode = 'graph'
/**
 * What the pane last drew, which a key or a turn of the wheel goes on from:
 * the view it drew the map in (the tree, wherever the graph had no room), the
 * room it gave the map and where the tree's window stood, the rows it gave
 * the list and the symbol the list started from, and the row of the pane's
 * body the list begins on. Where the graph's window stands is graphlet's to
 * keep.
 */
let shown: { mode: RippleMode; room: Room; pan: Pan; listRows: number; top: number; listAt: number } = {
  mode: 'graph',
  room: { columns: 0, rows: 0 },
  pan: { x: 0, y: 0 },
  listRows: 1,
  top: 0,
  listAt: 0,
}
/** The changes of the map on hand's scope as they were last read; undefined until they are read again. */
let since: Changes | undefined
/** How many times the map on hand was replaced or cleared: a reading begun before the last is of another map, and dropped. */
let readings = 0
/** Whether a mapper is being started, between the check that none is at work and the record of the new one. */
let isStarting = false
/** The mappers Ripple stopped waiting on before they reported: each call of theirs is refused. */
const dropped = new Set<string>()
/** The last row of the tree or the list a click selected, and when, which a second click soon after opens. */
let lastClick = { id: '', at: 0 }
/** Whether a call for a map has asked to start a mapping since the person last spoke: one may, each time. */
let hasAskedThisTurn = false
/** What wakes each step of a wait for a map that is held now. */
const wakers = new Set<() => void>()
/** How many steps of a wait for a map have been held: a step that returns with none held means none can be. */
let holds = 0
/** How many calls for a map wait now; a map that arrives while any waits is drawn in their rows, and opens no pane. */
let waiting = 0
/** How many times each mapper's report was refused for naming symbols wrongly. */
const refusals = new Map<string, number>()
/** The maps the map tool answered with, by the call's id, the latest last. */
const answered = new Map<string, RippleMap>()
/**
 * How the mappings Ripple waited on ended, by the mapper's id: the map it
 * reported, or null for one that ended without. A call that waits reads this
 * and not the session state, which reads as it stood when the call began.
 */
const endings = new Map<string, RippleMap | null>()

/** The elements every surface's table has. */
type Kit = Pick<Elements['terminal'], 'Box' | 'Text' | 'Button'>

const describe = (error: unknown): string => (error instanceof Error ? error.message : String(error))

const rootOf = async ($: EngineInterface): Promise<string> =>
  (await $.session.root()).replace(/\\/g, '/').replace(/\/+$/, '')

const storeKey = async ($: EngineInterface): Promise<string> => `map:${await $.session.root()}`

/** Keeps the last map across sessions. */
const persist = async ($: EngineInterface, value: RippleMap | null): Promise<void> => {
  try {
    if (value === null) await $.store.delete(await storeKey($))
    else await $.store.set(await storeKey($), value)
  } catch (error) {
    $.ui.log(`ripple: could not save the map: ${describe(error)}`, { to: 'debug' })
  }
}

/** A command's output under the session's root, given `stdin` when there is any, or undefined when it failed. */
const run = async ($: EngineInterface, argv: readonly string[], stdin?: string): Promise<string | undefined> => {
  try {
    const ran = await $.process.run(argv, {
      cwd: await $.session.root(),
      timeoutMs: GIT_TIMEOUT_MS,
      ...(stdin === undefined ? {} : { stdin }),
    })
    return ran.exitCode === 0 ? ran.stdout : undefined
  } catch {
    return undefined
  }
}

/** What a scope's changes are against: HEAD, or where this branch left the default one. */
const baseOf = async ($: EngineInterface, scope: RippleScope): Promise<Base | undefined> => {
  if (scope === 'uncommitted') return HEAD
  for (const command of DEFAULT_BRANCH_COMMANDS) {
    const branch = (await run($, command))?.trim() ?? ''
    if (branch === '') continue
    const ref = (await run($, mergeBaseCommand(branch)))?.trim() ?? ''
    if (ref !== '') return { ref, name: branch.replace(/^origin\//, '') }
  }
  return undefined
}

/** Reads a scope's changes from git, or says why they could not be read. */
const readTree = async ($: EngineInterface, scope: RippleScope): Promise<Changes | string> => {
  if ((await $.session.repo()) === null) return NOT_A_REPOSITORY
  const base = await baseOf($, scope)
  if (base === undefined) return NO_DEFAULT_BRANCH
  const diff = await run($, diffCommand(base.ref))
  const untracked = await run($, UNTRACKED_COMMAND)
  if (diff === undefined || untracked === undefined) return GIT_FAILED
  const hashing = hashInput(untracked)
  let hashes = hashing === undefined ? '' : await run($, HASH_COMMAND, hashing)
  if (hashes === undefined) {
    const each: string[] = []
    for (const argv of hashCommands(untracked)) each.push((await run($, argv))?.trim() ?? '')
    hashes = each.join('\n')
  }
  return readChanges(scope, base, diff, untracked, hashes)
}

const nothingToMap = (changes: Changes): string =>
  changes.scope === 'branch'
    ? `Ripple: nothing to map. This branch has no changes since ${changes.base.name}.`
    : 'Ripple: nothing to map. Git shows no uncommitted changes here. Change something, or run /ripple branch to map the whole branch.'

/** Whether the changes have moved on since the map was made, as they were last read. */
const isStaleOf = (held: RippleMap | null): boolean => held !== null && since !== undefined && since.print !== held.print

const refreshStatus = async ($: EngineInterface): Promise<void> => {
  const held = await read($, map)
  $.ui.status(statusText(held, (await read($, mapping)) !== null, isStaleOf(held)))
}

/**
 * Reads the changes of the map on hand again, and redraws when they read
 * otherwise than they did: whether they are still the ones the map was made
 * from, and which files were edited since. A reading that fails changes
 * nothing.
 */
const checkStale = async ($: EngineInterface): Promise<void> => {
  const reading = readings
  const held = await read($, map)
  if (held === null) return
  const changes = await readTree($, held.scope)
  if (reading !== readings || typeof changes === 'string' || changes.print === since?.print) return
  since = changes
  await refreshStatus($)
  $.ui.invalidate('ui.render')
}

/**
 * Opens the pane. Opened because the person asked, it is placed at any width
 * and asks for the keyboard. Opened when a report arrives it takes no
 * keyboard from them, and it may wait for a wider terminal: then a toast says
 * how to bring it up.
 */
const openPane = async ($: EngineInterface, isAsked: boolean): Promise<void> => {
  try {
    const opened = await $.ui.open({
      id: PANE,
      title: 'Ripple',
      columns: PANE_COLUMNS,
      ...(isAsked ? { focus: true as const } : {}),
    })
    if (!opened.isPlaced) $.ui.toast('Ripple: the map is ready. Run /ripple to open it.')
  } catch (error) {
    $.ui.log(`ripple: could not open the pane: ${describe(error)}`, { to: 'debug' })
  }
}

/** Wakes every held step of a wait for a map, to look again at how the mapping stands. */
const wake = (): void => {
  for (const resolve of wakers) resolve()
  wakers.clear()
}

/** Sets `key` to `value` in `kept`, as its latest, and lets the oldest go past `count`. */
const keepLast = <V,>(kept: Map<string, V>, key: string, value: V, count: number): void => {
  kept.delete(key)
  kept.set(key, value)
  for (const old of [...kept.keys()].slice(0, Math.max(0, kept.size - count))) kept.delete(old)
}

/**
 * Ends the wait on the mapper `agentId`, with the map it reported or none,
 * and wakes every call waiting on it. A mapping that has ended once keeps
 * how it ended, and another mapper's is left as it is.
 */
const endMapping = async ($: EngineInterface, agentId: string, made: RippleMap | null): Promise<void> => {
  await update($, mapping, at => (at?.agentId === agentId ? null : at))
  await refreshStatus($)
  if (!endings.has(agentId)) keepLast(endings, agentId, made, ENDINGS)
  refusals.delete(agentId)
  wake()
}

/** Whether the mapper Ripple is waiting on is still at work; one that ended without a word is forgotten. */
const isMapping = async ($: EngineInterface): Promise<boolean> => {
  const at = await read($, mapping)
  if (at === null) return false
  const agent = (await $.agent.list()).find(one => one.id === at.agentId)
  if (agent !== undefined && AT_WORK.includes(agent.status)) return true
  await endMapping($, at.agentId, null)
  return false
}

/** Stops a mapper Ripple started that is still at work, and says whether none is left at work. */
const stopMapper = async ($: EngineInterface, agentId: string): Promise<boolean> => {
  dropped.add(agentId)
  const agent = (await $.agent.list()).find(one => one.id === agentId)
  const isOurs = agent?.type === MAPPER_TYPE && agent.spawnedBy === 'ripple'
  if (agent === undefined || !isOurs || !AT_WORK.includes(agent.status)) return true
  try {
    await $.tool.call({ tool: 'TaskStop', task_id: agentId })
    return true
  } catch (error) {
    $.ui.log(`ripple: could not stop the mapper: ${describe(error)}`, { to: 'debug' })
    return false
  }
}

/**
 * Counts a call of the mapper Ripple is waiting on, and says in the pane what
 * it is doing; a call of any other agent changes nothing.
 */
const noteCall = async ($: EngineInterface, agentId: string, tool: string, args: Record<string, unknown>) => {
  const doing = describeCall(tool, args, await rootOf($))
  const path = tool === 'Read' && typeof args.file_path === 'string' ? args.file_path : undefined
  await update($, mapping, at =>
    at?.agentId !== agentId
      ? at
      : { ...at, doing, read: path === undefined || at.read.includes(path) ? at.read : [...at.read, path] },
  )
}

/**
 * Holds a call for a map until the mapper `agentId` ends, the person
 * interrupts the call, or `MAP_WAIT_MS` pass, and resolves to how it ended:
 * the map it reported, null where it ended without one, or undefined while
 * it is still at work. A hook's own time is bounded, and its clock stops only
 * while one of its `$` calls is in flight, so the wait is a chain of reads of
 * the store's `ripple:wait`, each held by this module's own hook on that key
 * until the mapping ends or `WAIT_STEP_MS` pass.
 */
const waitForMap = async ($: EngineInterface, agentId: string, signal: AbortSignal): Promise<RippleMap | null | undefined> => {
  const until = (await $.clock.now()) + MAP_WAIT_MS
  waiting += 1
  signal.addEventListener('abort', wake)
  try {
    while (!endings.has(agentId) && !signal.aborted && (await $.clock.now()) < until) {
      const agent = (await $.agent.list()).find(one => one.id === agentId)
      if (agent === undefined || !AT_WORK.includes(agent.status)) return endings.get(agentId) ?? null
      const held = holds
      await $.store.get('ripple:wait')
      if (holds === held) break
    }
    return endings.get(agentId)
  } finally {
    signal.removeEventListener('abort', wake)
    waiting -= 1
  }
}

/**
 * Whether the person lets a mapping Claude asked for start: undefined when
 * they do, else what Claude is told. Their permission rules for the map tool
 * decide, and where those would ask, Ripple asks them.
 */
const refusalOf = async ($: EngineInterface, changes: Changes, input: Record<string, unknown>): Promise<string | undefined> => {
  const verdict = await $.tool.check({ tool: MAP_TOOL, input })
  if (verdict.decision === 'allow') return undefined
  if (verdict.decision === 'deny') return MAP_SAYS.denied
  try {
    const answer = await $.ui.ask(
      `Claude asks Ripple to map ${describeChanges(changes)}. A background agent reads the code, which takes a minute or more. Map them?`,
      { options: [MAP_IT, NOT_NOW], header: 'Ripple' },
    )
    if (answer === MAP_IT) return undefined
    return answer === NOT_NOW ? MAP_SAYS.notNow : MAP_SAYS.wrote(answer)
  } catch {
    return MAP_SAYS.notNow
  }
}

/** What serves a map of a scope's changes: why there is none to map, the map on hand of them, the mapper at work, or nothing yet. */
type Sought =
  | { said: string }
  | { held: RippleMap; changes: Changes }
  | { busy: RippleMapping; isSame: boolean; changes: Changes }
  | { changes: Changes }

/**
 * Reads a scope's changes and finds what serves a map of them with `focus`,
 * or with any focus where `focus` is undefined: the map on hand when it was
 * made from these very changes, else the mapper at work, which is the same
 * when it was sent to map them. A reading that finds the map on hand current
 * notes it.
 */
const seek = async ($: EngineInterface, scope: RippleScope, focus: string | undefined): Promise<Sought> => {
  const changes = await readTree($, scope)
  if (typeof changes === 'string') return { said: changes }
  if (changes.files.length === 0) return { said: nothingToMap(changes) }
  const isFocused = (at: RippleOrigin): boolean => at.print === changes.print && (focus === undefined || at.focus === focus)
  const held = await read($, map)
  if (held !== null && isFocused(held)) {
    if (since?.print !== changes.print) {
      since = changes
      await refreshStatus($)
    }
    return { held, changes }
  }
  const at = (await isMapping($)) ? await read($, mapping) : null
  return at === null ? { changes } : { busy: at, isSame: isFocused(at), changes }
}

/** Starts a mapper on `changes` with `focus`; resolves to its id, or to why it could not, for the caller to say. */
const start = async ($: EngineInterface, changes: Changes, focus: string): Promise<{ agentId: string } | { said: string }> => {
  if (isStarting) return { said: 'Ripple: already starting a mapper.' }
  isStarting = true
  try {
    let isBusy = false
    await update($, mapping, at => {
      isBusy = at !== null
      return at
    })
    if (isBusy) return { said: 'Ripple: still mapping what was asked before. Run this again once that map is in.' }
    const spawned = await $.agent.spawn({
      subagentType: MAPPER_TYPE,
      description: `Map ${describeChanges(changes)}`,
      prompt: taskPrompt(changes, focus, await rootOf($)),
    })
    if (spawned.agentId === undefined) {
      return { said: `Ripple: could not start the mapper (${spawned.deny ?? 'no agent started'}).` }
    }
    const { agentId } = spawned
    await update($, mapping, () => ({
      agentId,
      scope: changes.scope,
      base: changes.base.name,
      focus,
      print: changes.print,
      prints: printsOf(changes),
      read: [],
      doing: '',
    }))
    await refreshStatus($)
    return { agentId }
  } finally {
    isStarting = false
  }
}

/**
 * Finds the map of a scope's changes on hand, made from these very changes
 * with this focus, or the mapper at work on them, or else starts a mapper on
 * them; with `isForced`, starts one even over a current map, unless a mapper
 * is at work. Resolves to why there is none to show, for the caller to say.
 */
const serveMap = async (
  $: EngineInterface,
  scope: RippleScope,
  focus: string,
  isForced: boolean,
): Promise<string | undefined> => {
  const sought = await seek($, scope, focus)
  if ('said' in sought) return sought.said
  if ('busy' in sought) {
    return sought.isSame ? undefined : 'Ripple: still mapping what was asked before. Run this again once that map is in.'
  }
  if ('held' in sought && !isForced) return undefined
  const started = await start($, sought.changes, focus)
  return 'said' in started ? started.said : undefined
}

const styleOf = (paint: Paint): TextProps => {
  const color = COLORS[paint]
  return { ...(color === undefined ? {} : { color }), ...(paint === 'dim' ? { dimColor: true } : {}) }
}

const LEGEND_LABELS = LEGEND.map(mark => `${mark.glyph} ${mark.label}`)

const legend = ({ Box, Text }: Kit): RenderElement => (
  <Box flexDirection="row" flexWrap="wrap" columnGap={2}>
    {LEGEND.map((mark, index) => (
      <Text {...styleOf(mark.paint)}>{LEGEND_LABELS[index]}</Text>
    ))}
  </Box>
)

/** The pane's keys under a map with symbols, in the order they are drawn. */
const keysOf = (drawn: RippleMode): Array<{ key: string; label: string; isDim: boolean }> => [
  { key: 'h', label: '←', isDim: true },
  { key: 'j', label: '↓', isDim: true },
  { key: 'k', label: '↑', isDim: true },
  { key: 'l', label: '→', isDim: true },
  { key: 'u', label: 'symbol ↑', isDim: true },
  { key: 'd', label: 'symbol ↓', isDim: true },
  { key: 'n', label: 'next flagged', isDim: true },
  { key: 't', label: drawn === 'tree' ? 'graph view' : 'tree view', isDim: true },
  { key: ASK, label: 'ask Claude', isDim: false },
  { key: REMAP, label: 're-map', isDim: false },
  { key: OPEN, label: 'open', isDim: false },
]

/** The variables that say which terminal the session runs in and which editor the person uses. */
const environment = async ($: EngineInterface) => ({
  TERM_PROGRAM: await $.env.get('TERM_PROGRAM'),
  VSCODE_GIT_ASKPASS_MAIN: await $.env.get('VSCODE_GIT_ASKPASS_MAIN'),
  VISUAL: await $.env.get('VISUAL'),
  EDITOR: await $.env.get('EDITOR'),
})

/**
 * Whether `file`, a path in the project, is a file there: `missing` where
 * nothing is, `elsewhere` where what is there is not a plain file or leads,
 * with its links followed, out of the project.
 */
const projectFile = async ($: EngineInterface, file: string): Promise<'file' | 'missing' | 'elsewhere'> => {
  const root = await rootOf($)
  const [home, found] = await Promise.all([
    $.fs.stat(root, { resolve: true }).catch(() => undefined),
    $.fs.stat(`${root}/${file}`, { resolve: true }).catch(() => undefined),
  ])
  if (found === undefined) return 'missing'
  const isInside = (found.realPath ?? '').replace(/\\/g, '/').startsWith(`${(home?.realPath ?? root).replace(/\\/g, '/')}/`)
  return found.kind === 'file' && isInside ? 'file' : 'elsewhere'
}

/**
 * Opens a symbol's file at its line in the person's editor, with the first of
 * its commands that runs, from the plugin's own folder and with no shell.
 * Only a file inside the project, links followed, is opened. Resolves to what
 * the person is told.
 */
const openSymbol = async ($: EngineInterface, node: RippleNode): Promise<string> => {
  const path = `${await rootOf($)}/${node.file}`
  const found = await projectFile($, node.file)
  if (found === 'missing') return `Ripple: ${node.file} is not there to open.`
  if (found === 'elsewhere') return `Ripple: ${node.file} is not a file in this project.`
  const commands = editorCommands(await environment($), path, node.line)
  if (commands.length === 0) {
    return `Ripple: found no editor to open ${node.file} in (looked for the terminal of VS Code, Cursor, VSCodium, Windsurf, or Zed, then VISUAL and EDITOR). It is at ${path}.`
  }
  for (const argv of commands) {
    const ran = await $.process.run(argv, { cwd: $.plugin.root, timeoutMs: EDITOR_TIMEOUT_MS }).catch(() => undefined)
    if (ran?.exitCode === 0) return `Ripple: opened ${locOf(node)} with ${argv[0]}.`
  }
  return `Ripple: could not open ${node.file} with ${commands.map(argv => argv[0]).join(' or ')}. Is the editor's command on your PATH?`
}

/**
 * Opens the selected symbol's file, of the map on hand or of `held`; with
 * `path`, the file at that path, at the selected symbol where it holds that
 * one and else at its first.
 */
const open = async ($: EngineInterface, path?: string, held?: RippleMap): Promise<void> => {
  const shown = held ?? (await read($, map))
  if (shown === null) return
  const at = selectedOf(shown, (await read($, view)).selected)
  const file = path === undefined ? undefined : filesOf(shown).files.find(one => one.path === path)
  const node = path === undefined ? at : file === undefined ? undefined : symbolIn(file, at?.id ?? null)
  if (node !== undefined) $.ui.toast(await openSymbol($, node))
}

/** Asks Claude, in the conversation, about the selected node. */
const ask = async ($: EngineInterface): Promise<void> => {
  const held = await read($, map)
  const node = held === null ? undefined : selectedOf(held, (await read($, view)).selected)
  if (held === null || node === undefined) return
  $.ui.toast(`Ripple: asked Claude about ${node.name}.`)
  await $.prompt.submit({ text: askPrompt(node, held) })
}

const isPan = (value: unknown): value is Pan =>
  typeof value === 'object' &&
  value !== null &&
  Number.isFinite((value as Pan).x) &&
  Number.isFinite((value as Pan).y)

/**
 * Scrolls the map by cells, or by turns of the wheel: the graph through
 * graphlet, and the tree's window from where the person left it, or where it
 * was last drawn.
 */
const scrollMap = async ($: EngineInterface, by: Pan | number): Promise<void> => {
  const held = await read($, map)
  if (held === null) return
  if (shown.mode === 'graph') return $.graphlet.scroll({ site: PANE, by })
  const files = filesOf(held)
  await update($, view, seen => ({ ...seen, pan: treeView.scroll(files, shown.room, seen.pan ?? shown.pan, by) }))
}

/** Scrolls the list under the map from where the person left it, or where it was last drawn, by rows. */
const scrollSymbols = async ($: EngineInterface, by: number): Promise<void> => {
  const held = await read($, map)
  if (held === null) return
  const file = fileOf(filesOf(held), selectedOf(held, (await read($, view)).selected)?.id ?? null)
  if (file === undefined) return
  await update($, view, seen => ({ ...seen, top: scrollList(file, shown.listRows, seen.top ?? shown.top, by) }))
}

/**
 * Selects a symbol. The list goes back to following the selection, and so
 * does the map's window when the symbol is in another file than the one
 * selected; a symbol already selected changes nothing.
 */
const select = async ($: EngineInterface, held: RippleMap, to: string | null): Promise<void> => {
  const files = filesOf(held)
  const from = selectedOf(held, (await read($, view)).selected)?.id ?? null
  if (to === null || to === from) return
  const isSameFile = fileOf(files, to) === fileOf(files, from)
  await update($, view, seen => ({ ...seen, selected: to, pan: isSameFile ? seen.pan : null, top: null }))
}

/**
 * The symbol a move from the selected file lands on, in the view the pane
 * last drew: the one selected while the move stays in its file, else the
 * first of the file it reaches.
 */
const stepped = async ($: EngineInterface, files: FileMap, at: string | null, move: Move): Promise<string | null> => {
  if (shown.mode === 'tree') return treeView.step(files, at, move, shown.room, shown.pan)
  const path = await $.graphlet.step({ site: PANE, move })
  const file = files.files.find(one => one.path === path)
  return (file === undefined ? undefined : symbolIn(file, at)?.id) ?? at
}

/**
 * Does what one key of the pane does: a Button's, or a key the map or the
 * list was handed. In the list, up and down go through the file's symbols.
 * The two views are drawn by different mods, so switching between them takes
 * the keyboard from the one that had it, and the pane asks for it back.
 */
const press = async ($: EngineInterface, key: string, isInList = false): Promise<void> => {
  try {
    const held = await read($, map)
    if (held === null) return
    const files = filesOf(held)
    const at = selectedOf(held, (await read($, view)).selected)?.id ?? null
    const file = fileOf(files, at)
    const move = MOVES[key]
    const listMove = LIST_MOVES[key] ?? (isInList && (move === 'up' || move === 'down') ? move : undefined)
    if (listMove !== undefined) {
      if (file !== undefined) await select($, held, stepInList(file, at, listMove))
    } else if (move !== undefined) {
      await select($, held, await stepped($, files, at, move))
    } else if (key === 'n') {
      await select($, held, nextFlagged(held, at))
    } else if (key === 't') {
      const other: RippleMode = shown.mode === 'tree' ? 'graph' : 'tree'
      await update($, view, seen => ({ ...seen, mode: other, pan: null }))
      await openPane($, true)
    } else if (key === OPEN || key === 'return') {
      await open($)
    } else if (key === ASK) {
      await ask($)
    } else if (key === REMAP) {
      const said = await serveMap($, held.scope, held.focus, true)
      if (said !== undefined) $.ui.toast(said)
    }
  } catch (error) {
    $.ui.toast(`Ripple: ${describe(error)}`)
  }
}

export const register: Register = (on, options) => {
  firstMode = options.view === 'tree' ? 'tree' : 'graph'

  on('session.start', async ($, e, next) => {
    try {
      await $.tool.register({
        name: 'report',
        description: REPORT_DESCRIPTION,
        inputSchema: REPORT_SCHEMA,
        isDeferred: true,
      })
      await $.tool.register({
        name: MAP_NAME,
        description: MAP_DESCRIPTION,
        inputSchema: MAP_SCHEMA,
        isDeferred: false,
      })
      await $.agent.register({
        name: MAPPER_NAME,
        description: MAPPER_DESCRIPTION,
        prompt: MAPPER_PROMPT,
        tools: mapperTools(await $.tool.list().then(tools => tools.map(tool => tool.name), () => [])),
        background: true,
      })
      await $.command.register({
        name: 'ripple',
        description: 'Map what your changes reach',
        argumentHint: '[branch] [focus] | reset',
      })
      if ((await read($, map)) === null) {
        const kept = readStored(await $.store.get(await storeKey($)), await rootOf($))
        if (kept !== null) await update($, map, () => kept)
      }
      await refreshStatus($)
      await checkStale($)
    } catch (error) {
      $.ui.log(`ripple: session start: ${describe(error)}`, { to: 'debug' })
    }
    return next(e)
  })

  on('agent.offer', { agent: 'ripple:mapper' }, () => ({ isOffered: false })).catch(($, e, next) => next(e))

  on('command.run', { command: 'ripple' }, async ($, e) => {
    let said: string | undefined
    try {
      const request = readRequest(e.args)
      if (request.verb === 'map') {
        said = await serveMap($, request.scope, request.focus, false)
        if (said === undefined) await openPane($, true)
      } else {
        const at = await read($, mapping)
        await update($, map, () => null)
        since = undefined
        readings += 1
        if (at !== null) await endMapping($, at.agentId, null)
        else await refreshStatus($)
        await persist($, null)
        await $.ui.close({ id: PANE }).catch(() => undefined)
        const isStopped = at === null || (await stopMapper($, at.agentId))
        said =
          at === null
            ? 'Ripple: cleared the map.'
            : isStopped
              ? 'Ripple: stopped the mapper and cleared the map.'
              : 'Ripple: cleared the map. The mapper could not be stopped: it runs on, and its map will be dropped.'
      }
    } catch (error) {
      said = `Ripple: /ripple failed (${describe(error)}).`
    }
    return said === undefined ? {} : { text: said }
  })

  on('tool.check', async ($, e, next) => {
    const verdict = await next(e)
    if (e.agentId === undefined || verdict.decision !== 'ask') return verdict
    const agent = (await $.agent.list()).find(one => one.id === e.agentId)
    return agent?.type === MAPPER_TYPE ? { decision: 'deny', reason: NO_ASKING } : verdict
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: 'mcp__ripple__report' }, async ($, e) => {
    const at = await read($, mapping)
    if (e.agentId !== undefined && dropped.has(e.agentId)) return { deny: STOPPED }
    if (at === null || e.agentId !== at.agentId) {
      return { deny: REPORT_SAYS.notWaited }
    }
    const root = await rootOf($)
    const reported = readReport(e, root)
    if ('error' in reported) {
      return { deny: REPORT_SAYS.unread(reported.error) }
    }
    if ((refusals.get(at.agentId) ?? 0) < NAME_CHECKS) {
      const files = [...new Set(reported.report.nodes.map(node => node.file))]
      const texts = new Map<string, string>()
      for (const file of files) {
        const text = (await projectFile($, file)) === 'file' ? await $.fs.read(`${root}/${file}`).catch(() => undefined) : undefined
        if (typeof text === 'string') texts.set(file, text)
      }
      const misnamed = misnamedIn(reported.report, texts)
      if (misnamed.length > 0) {
        refusals.set(at.agentId, (refusals.get(at.agentId) ?? 0) + 1)
        return { deny: misnamedReply(misnamed) }
      }
    }
    if (dropped.has(at.agentId)) return { deny: STOPPED }
    const made: RippleMap = {
      ...reported.report,
      scope: at.scope,
      base: at.base,
      focus: at.focus,
      print: at.print,
      prints: at.prints,
    }
    await update($, map, () => made)
    await update($, view, seen => ({ ...seen, selected: null, pan: null, top: null }))
    since = undefined
    readings += 1
    await persist($, made)
    const isAwaited = waiting > 0
    await endMapping($, at.agentId, made)
    await checkStale($).catch(error => $.ui.log(`ripple: reading the changes: ${describe(error)}`, { to: 'debug' }))
    if (!isAwaited) await openPane($, false)
    return { result: reportReply(reported.report, reported.notes) }
  }).catch(() => ({ deny: REPORT_SAYS.failed }))

  /**
   * Claude asks for a map. It is answered with the map on hand of the changes
   * as they stand, whatever its focus; else, with the person's leave, a
   * mapper is started, or the one at work on these changes is joined, and the
   * call waits for its map. Only the main conversation asks.
   */
  on('tool.call', { tool: 'mcp__ripple__map' }, async ($, e, next) => {
    if (e.agentId !== undefined) return { deny: MAP_SAYS.onlyMain }
    const input = e as unknown as Record<string, unknown>
    const scope: RippleScope = input.scope === 'branch' ? 'branch' : 'uncommitted'
    const answer = (held: RippleMap, changes: Changes): { result: string } => {
      keepLast(answered, e.tool_use_id, held, ANSWERED_MAPS)
      return { result: mapAnswer(held, editedSince(held, changes)) }
    }
    const sought = await seek($, scope, undefined)
    if ('said' in sought) return { result: sought.said }
    if ('held' in sought) return answer(sought.held, sought.changes)
    if ('busy' in sought && !sought.isSame) return { result: MAP_SAYS.otherMapping }
    let agentId = 'busy' in sought ? sought.busy.agentId : undefined
    if (agentId === undefined) {
      if (hasAskedThisTurn) return { result: MAP_SAYS.onceATurn }
      hasAskedThisTurn = true
      const refusal = await refusalOf($, sought.changes, { scope })
      if (refusal !== undefined) return { result: refusal }
      const started = await start($, sought.changes, '')
      if ('said' in started) return { result: started.said }
      agentId = started.agentId
    }
    try {
      const made = await waitForMap($, agentId, next.signal)
      if (made === undefined) return { result: MAP_SAYS.stillMapping }
      return made === null ? { result: MAP_SAYS.endedEmpty } : answer(made, since ?? sought.changes)
    } catch (error) {
      $.ui.log(`ripple: waiting for a map: ${describe(error)}`, { to: 'debug' })
      return { result: MAP_SAYS.stillMapping }
    }
  }).catch(() => ({ result: MAP_SAYS.failed }))

  /** Holds one step of a wait for a map, until the mapping ends or `WAIT_STEP_MS` pass. */
  on('store.get', { key: 'ripple:wait' }, async ($, e, next) => {
    if (next.origin.plugin !== 'ripple') return next(e)
    holds += 1
    let waker = (): void => undefined
    try {
      await Promise.race([new Promise<void>(resolve => wakers.add((waker = resolve))), $.clock.sleep(WAIT_STEP_MS)])
    } finally {
      wakers.delete(waker)
    }
    return { value: undefined }
  }).catch(($, e, next) => next(e))

  /** A prompt of the person's own lets a call for a map ask once more to start a mapping. */
  on('prompt.submit', async ($, e, next) => {
    const isPerson = e.origin.kind === 'composer' || e.origin.kind === 'bridge' || e.origin.kind === 'sdk'
    if (isPerson && e.command === undefined && e.isMeta !== true) hasAskedThisTurn = false
    return next(e)
  }).catch(($, e, next) => next(e))

  on('session.end', async ($, e, next) => {
    wake()
    return next(e)
  }).catch(($, e, next) => next(e))

  /** The row of a call for a map that is waiting says how far along its mapper is. */
  on('ui.render', { component: 'ToolUse' }, async ($, e, next) => {
    const at = e.props.tool === MAP_TOOL && e.props.isRunning ? await read($, mapping) : null
    if (at === null) return next(e)
    const { Box, Text } = $.ui.resolve(e)
    return (
      <Box flexDirection="column">
        {await next(e)}
        <Text dimColor wrap="truncate-end">{`  ${progressText(at)}`}</Text>
      </Box>
    )
  }).catch(($, e, next) => next(e))

  /** The row of the map tool's answer draws the map it answered with, through graphlet. */
  on('ui.render', { component: 'ToolResult' }, async ($, e, next) => {
    const held = e.props.tool === MAP_TOOL ? answered.get(e.requestId) : undefined
    if (held === undefined || held.nodes.length === 0) return next(e)
    const { Box, Text } = $.ui.resolve(e)
    const columns = Math.max(MIN_COLUMNS, (e.viewport?.columns ?? PANE_COLUMNS) - 2)
    await $.graphlet.show({ site: e.requestId, graph: graphOf(filesOf(held)), columns, rows: TOOL_ROWS })
    return (
      <Box flexDirection="column">
        <Text bold wrap="truncate-end">
          {headerText(held)}
        </Text>
        <Text dimColor wrap="truncate-end">{`${originText(held)} · ${commandOf(held)} opens it in the pane`}</Text>
        {await next(e)}
      </Box>
    )
  }).catch(($, e, next) => next(e))

  /**
   * Watches the calls of agents: the mapper Ripple waits on has each call
   * counted for the pane and passed on as it came, and a mapper Ripple
   * stopped is refused every call.
   */
  on('tool.call', async ($, e, next) => {
    if (e.agentId === undefined) return next(e)
    if (dropped.has(e.agentId)) return { deny: STOPPED }
    if ((await read($, mapping))?.agentId === e.agentId) {
      await noteCall($, e.agentId, e.tool, e as unknown as Record<string, unknown>)
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    try {
      if (e.agentId === undefined) {
        await checkStale($)
      } else if ((await read($, mapping))?.agentId === e.agentId) {
        await endMapping($, e.agentId, null)
        $.ui.toast('Ripple: the mapper ended without a map. Run /ripple to try again.')
      }
    } catch (error) {
      $.ui.log(`ripple: turn end: ${describe(error)}`, { to: 'debug' })
    }
    return done
  })

  /**
   * Answers the pane's keys. A Button's own closure runs beneath this
   * module's hooks, where a mapper it started would be out of their reach.
   */
  on('ui.press', { plugin: 'ripple', component: 'Pane', requestId: 'ripple' }, async ($, e) => {
    await press($, e.element)
    return { element: e.element }
  })

  on('ui.message', async ($, e, next) => {
    if (e.requestId !== PANE || typeof e.data !== 'object' || e.data === null) return next(e)
    const { select: picked, scroll, key } = e.data as { select?: unknown; scroll?: unknown; key?: unknown }
    const held = await read($, map)
    if (typeof picked === 'string' && held !== null) {
      const now = await $.clock.now()
      const isDouble = picked === lastClick.id && now - lastClick.at <= DOUBLE_CLICK_MS
      lastClick = isDouble ? { id: '', at: 0 } : { id: picked, at: now }
      await select($, held, picked)
      if (isDouble) await open($)
    } else if (typeof key === 'string') {
      await press($, key, e.element === 'list')
    }
    else if (isPan(scroll)) await scrollMap($, scroll)
    return {}
  })

  /** Graphlet says which file the person picked on the graph: its box clicked, or an arrow key over it. */
  on('graphlet.select', async ($, e, next) => {
    const held = e.site === PANE ? await read($, map) : null
    const file = held === null ? undefined : filesOf(held).files.find(one => one.path === e.node)
    if (held !== null && file !== undefined) {
      const at = selectedOf(held, (await read($, view)).selected)?.id ?? null
      await select($, held, symbolIn(file, at)?.id ?? null)
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  /** Graphlet says the person opened a file on a graph, the pane's or an answer's: return on it, or a double click. */
  on('graphlet.open', async ($, e, next) => {
    const answeredMap = answered.get(e.site)
    if (e.site === PANE || answeredMap !== undefined) await open($, e.node, answeredMap)
    return next(e)
  }).catch(($, e, next) => next(e))

  /** Graphlet hands on the keys pressed over the graph that are the pane's, not its own. */
  on('graphlet.key', async ($, e, next) => {
    if (e.site === PANE) await press($, e.key)
    return next(e)
  }).catch(($, e, next) => next(e))

  on('ui.scroll', { component: 'Pane', requestId: 'ripple' }, async ($, e, next) => {
    if (e.origin.kind !== 'person' || e.pointer === undefined || e.contentRows > e.bodyRows) return next(e)
    if (e.pointer.row < shown.listAt) await scrollMap($, e.by)
    else await scrollSymbols($, e.by)
    return {}
  }).catch(($, e, next) => next(e))

  on('ui.render', { component: 'Pane', requestId: 'ripple' }, async ($, e, next) => {
    const held = await read($, map)
    const at = await read($, mapping)
    const seen = await read($, view)
    const columns = Math.max(MIN_COLUMNS, e.props.bodyColumns)

    const kit: Kit = $.ui.resolve(e)
    const { Box, Text, Button } = kit
    const hasNodes = held !== null && held.nodes.length > 0
    const edited = held === null || since === undefined ? [] : editedSince(held, since)
    const notice =
      at !== null
        ? progressText(at)
        : held === null
          ? 'No map yet. Run /ripple to map your changes.'
          : isStaleOf(held)
            ? movedText(edited, REMAP)
            : undefined
    const noticeLine = notice !== undefined && (
      <Text wrap="truncate-end" {...(at === null ? { dimColor: true } : { color: 'warning' })}>
        {notice}
      </Text>
    )
    const button = (key: string, label: string, isDim = false): RenderElement => (
      <Button
        key={key}
        label={label}
        hotkey={key}
        plain
        {...(isDim ? { dimColor: true } : {})}
        onPress={() => undefined}
      />
    )

    if (e.surface !== 'terminal') {
      let picture: RenderElement | false = false
      if (hasNodes) {
        try {
          await $.graphlet.show({ site: PANE, graph: graphOf(filesOf(held)), columns, rows: WHOLE_ROWS })
          picture = await next(e)
        } catch (error) {
          $.ui.log(`ripple: graphlet could not draw the graph: ${describe(error)}`, { to: 'debug' })
        }
      }
      return (
        <Box flexDirection="column" gap={1}>
          <Box flexDirection="column">
            <Text bold>{held === null ? 'Ripple' : headerText(held)}</Text>
            {held !== null && <Text dimColor>{originText(held)}</Text>}
            {held?.summary !== undefined && <Text wrap="wrap">{held.summary}</Text>}
            {noticeLine}
          </Box>
          {picture}
          {hasNodes && (
            <Box flexDirection="column">
              {flagged(held).map(one => (
                <Text wrap="wrap">
                  <Text {...styleOf(markOf(one).paint)}>{`${markOf(one).glyph} `}</Text>
                  <Text bold>{one.name}</Text>
                  <Text dimColor>{`  ${locOf(one)}`}</Text>
                  {one.reason === undefined ? '' : `  ${one.reason}`}
                </Text>
              ))}
            </Box>
          )}
          {hasNodes && legend(kit)}
          {held !== null && button(REMAP, 're-map')}
        </Box>
      )
    }

    const { Client } = $.ui.resolve(e)
    const files = hasNodes ? filesOf(held) : undefined
    const node = hasNodes ? selectedOf(held, seen.selected) : undefined
    const file = files === undefined ? undefined : fileOf(files, node?.id ?? null)
    const graph = files === undefined ? undefined : graphOf(files)
    let asked = modeIn(seen.mode ?? firstMode, { columns, rows: WHOLE_ROWS })
    let mapNeeds = 0
    if (graph !== undefined && asked === 'graph') {
      try {
        mapNeeds = (await $.graphlet.measure({ graph, columns })).rows
      } catch (error) {
        asked = 'tree'
        $.ui.log(`ripple: graphlet could not draw the graph: ${describe(error)}`, { to: 'debug' })
      }
    }
    if (files !== undefined && asked === 'tree') {
      mapNeeds = treeView.draw(files, null, { columns, rows: WHOLE_ROWS }, ORIGIN).rows.length
    }
    const plan = planOf(
      { columns, rows: e.props.scroll.bodyRows },
      {
        summary: held?.summary ?? '',
        hasNotice: notice !== undefined,
        legend: LEGEND_LABELS,
        keys: keysOf(asked).map(one => one.label),
        symbols: Math.max(1, ...(files?.files ?? []).map(one => one.symbols.length)),
        mapNeeds,
      },
    )
    const room = { columns, rows: plan.mapRows }
    const gap = plan.isCompact ? 0 : 1
    const mode = modeIn(asked, room)
    const keys = keysOf(mode).filter(one => one.key !== 't' || modeIn('graph', room) === 'graph')

    let drawn: RenderElement | false = false
    if (files !== undefined && graph !== undefined && file !== undefined && node !== undefined && hasNodes) {
      const top = seen.top ?? showInList(file, node.id, plan.listRows, shown.top)
      const says = `${listSays(file, plan.listRows, top)}${edited.includes(file.path) ? ' · edited' : ''}`
      let pan = shown.pan
      let drawnMode = mode
      let pictureRows = 0
      let picture: RenderElement | undefined
      if (mode === 'graph') {
        try {
          pictureRows = (await $.graphlet.show({ site: PANE, graph, ...room, selected: file.path })).rows
          picture = await next(e)
        } catch (error) {
          drawnMode = 'tree'
          $.ui.log(`ripple: graphlet could not draw the graph: ${describe(error)}`, { to: 'debug' })
        }
      }
      if (picture === undefined) {
        pan = seen.pan ?? treeView.show(files, node.id, room, shown.pan)
        const tree = treeView.draw(files, node.id, room, pan)
        pictureRows = tree.rows.length
        picture = <Client key="map" module="./pane.tsx" props={tree} />
      }
      shown = { mode: drawnMode, room, pan, listRows: plan.listRows, top, listAt: plan.mapTop + pictureRows + gap }
      drawn = (
        <Box flexDirection="column" marginTop={gap}>
          {picture}
          <Box flexDirection="column" marginTop={gap}>
            <Text wrap="truncate-end">
              <Text bold>{`▸ ${clipStart(file.path, Math.max(1, columns - says.length - OVER_LIST_CHARS))}`}</Text>
              <Text dimColor>{` · ${says}`}</Text>
            </Text>
            <Box flexDirection="column" height={plan.listRows + plan.detailRows} overflow="hidden">
              <Client
                key="list"
                module="./pane.tsx"
                props={drawList(file, node.id, { columns, rows: plan.listRows }, top)}
              />
              {!plan.isCompact && (
                <Text wrap="truncate-end">
                  <Text bold>{node.name}</Text>
                  <Text dimColor>{` · ${factsOf(held, node)}`}</Text>
                </Text>
              )}
              {node.reason !== undefined && (
                <Text wrap={plan.isCompact ? 'truncate-end' : 'wrap'} {...styleOf(markOf(node).paint)}>
                  {node.reason}
                </Text>
              )}
            </Box>
          </Box>
        </Box>
      )
    }
    return (
      <Box flexDirection="column">
        <Text bold wrap="truncate-end">
          {held === null ? 'Ripple' : headerText(held)}
        </Text>
        {!plan.isCompact && held !== null && (
          <Text dimColor wrap="truncate-end">
            {originText(held)}
          </Text>
        )}
        {!plan.isCompact && held?.summary !== undefined && <Text wrap="wrap">{held.summary}</Text>}
        {noticeLine}
        {!plan.isCompact && hasNodes && legend(kit)}
        {drawn}
        {held !== null && (
          <Box flexDirection="row" flexWrap="wrap" columnGap={2} marginTop={gap}>
            {hasNodes ? keys.map(one => button(one.key, one.label, one.isDim)) : button(REMAP, 're-map')}
          </Box>
        )}
      </Box>
    )
  })
}

