import type { RippleScope } from '../types'

// The changes Ripple maps, as git reports them: register.tsx runs the
// commands these functions name and hands back what they printed.

/** What `/ripple <args>` asks for. */
export type Request = { verb: 'map'; scope: RippleScope; focus: string } | { verb: 'reset' }

/** `reset` stands alone, `branch` picks the scope, and any other words are what to focus on. */
export function readRequest(args: string): Request {
  const words = args.trim().split(/\s+/).filter(word => word !== '')
  const [first = '', ...rest] = words
  const verb = first.toLowerCase()
  if (rest.length === 0 && verb === 'reset') return { verb }
  if (verb === 'branch') return { verb: 'map', scope: 'branch', focus: rest.join(' ') }
  return { verb: 'map', scope: 'uncommitted', focus: words.join(' ') }
}

/** git, with paths printed as they are and no file system monitor of the repository's own to run. */
const GIT = ['git', '-c', 'core.quotePath=false', '-c', 'core.fsmonitor=false'] as const
/** Everything under the directory the command runs in. */
const PATHS = ['--', '.'] as const
/** The most untracked files whose contents are part of a print. */
const HASHED_FILES = 200

/**
 * The working tree against `ref`, one hunk per change and no context lines,
 * with whole hashes and renames found, spelled so that nothing in the
 * person's git configuration changes its shape.
 */
export function diffCommand(ref: string): string[] {
  return [
    ...GIT,
    'diff',
    ref,
    '--relative',
    '--unified=0',
    '--full-index',
    '--find-renames',
    '--no-color',
    '--no-ext-diff',
    '--no-textconv',
    '--src-prefix=a/',
    '--dst-prefix=b/',
    ...PATHS,
  ]
}

/** The files git does not track yet, which no diff shows, each name ended by a NUL and none quoted. */
export const UNTRACKED_COMMAND: readonly string[] = [
  ...GIT,
  'ls-files',
  '-z',
  '--others',
  '--exclude-standard',
  ...PATHS,
]

/**
 * What the untracked files hold, one hash a line, since their names alone do
 * not say when one is edited: of each file as it is on disk, through no
 * filter. The paths go in on stdin, a line each, as `hashInput` writes them.
 */
export const HASH_COMMAND: readonly string[] = [...GIT, 'hash-object', '--no-filters', '--stdin-paths']

/** The names in the listing of untracked files. */
function untrackedPaths(listing: string): string[] {
  return listing.split('\0').filter(path => path !== '')
}

/**
 * The untracked files that are hashed: the first `HASHED_FILES` that are
 * files, not a repository of their own git lists as a folder, and whose names
 * `--stdin-paths` reads as they are: on one line, not opening with a quote.
 */
function hashedPaths(listing: string): string[] {
  return untrackedPaths(listing)
    .filter(path => !/[\n\r]/.test(path) && !path.startsWith('"') && !path.endsWith('/'))
    .slice(0, HASHED_FILES)
}

/** What `HASH_COMMAND` is given on stdin for these untracked files; undefined when none is hashed. */
export function hashInput(untracked: string): string | undefined {
  const paths = hashedPaths(untracked)
  return paths.length === 0 ? undefined : `${paths.join('\n')}\n`
}

/**
 * The commands that hash the same files one at a time, for when hashing them
 * at once fails on one, as on a link that leads nowhere: each answers alone.
 */
export function hashCommands(untracked: string): string[][] {
  return hashedPaths(untracked).map(path => [...GIT, 'hash-object', '--no-filters', '--', path])
}

/** Where the default branch is looked for, first hit wins. */
export const DEFAULT_BRANCH_COMMANDS: ReadonlyArray<readonly string[]> = [
  [...GIT, 'symbolic-ref', '--quiet', '--short', 'refs/remotes/origin/HEAD'],
  [...GIT, 'rev-parse', '--verify', '--quiet', '--abbrev-ref', 'main'],
  [...GIT, 'rev-parse', '--verify', '--quiet', '--abbrev-ref', 'master'],
]

/** The commit the current branch left `branch` at. */
export function mergeBaseCommand(branch: string): string[] {
  return [...GIT, 'merge-base', 'HEAD', branch]
}

export type ChangedFile = {
  /** Relative to the project root, forward slashes. */
  file: string
  status: 'modified' | 'added' | 'deleted' | 'renamed'
  /** How many separate places the diff touches it; 0 for a file git does not track yet. */
  hunks: number
  /** Its part of the diff, from its `diff --git` line; '' for a file git does not track yet. */
  diff: string
  /**
   * What tells an edit to it: the hash of what it holds now, as its `index`
   * line or `git hash-object` gives it, or for a rename with nothing else
   * changed the print of its part of the diff; '' where it was not hashed.
   */
  print: string
  /** The old path of a renamed file. */
  from?: string
}

/** What a scope's changes are against: `ref` as git is asked for it, `name` as the person would say it. */
export type Base = { ref: string; name: string }

export const HEAD: Base = { ref: 'HEAD', name: 'HEAD' }

export type Changes = {
  scope: RippleScope
  base: Base
  files: ChangedFile[]
  /** Two readings with one print hold the same changes. */
  print: string
}

function pathOf(value: string): string {
  return value.trim().replace(/^"|"$/g, '')
}

function withoutPrefix(path: string): string {
  return path.replace(/^[ab]\//, '')
}

/** Reads one file's part of `git diff --unified=0`: its `diff --git` line and every line up to the next file's. */
function diffFile(part: string): ChangedFile {
  const [first = '', ...rest] = part.split('\n').map(raw => (raw.endsWith('\r') ? raw.slice(0, -1) : raw))
  const same = /^diff --git a\/(.+) b\/\1$/.exec(first)
  const current: ChangedFile = { file: pathOf(same?.[1] ?? ''), status: 'modified', hunks: 0, diff: part, print: printOf(part) }
  let isHeader = true
  for (const line of rest) {
    if (line.startsWith('@@ ')) {
      current.hunks += 1
      isHeader = false
    } else if (!isHeader) {
      continue
    } else if (line.startsWith('index ')) {
      current.print = /\.\.([0-9a-f]+)/.exec(line)?.[1] ?? current.print
    } else if (line.startsWith('new file mode')) {
      current.status = 'added'
    } else if (line.startsWith('deleted file mode')) {
      current.status = 'deleted'
    } else if (line.startsWith('rename from ')) {
      current.status = 'renamed'
      current.from = pathOf(line.slice('rename from '.length))
    } else if (line.startsWith('rename to ')) {
      current.file = pathOf(line.slice('rename to '.length))
    } else if (line.startsWith('+++ ') && !line.endsWith('/dev/null')) {
      current.file = withoutPrefix(pathOf(line.slice(4)))
    } else if (line.startsWith('--- ') && !line.endsWith('/dev/null') && current.file === '') {
      current.file = withoutPrefix(pathOf(line.slice(4)))
    }
  }
  return current
}

/** Reads `git diff --unified=0` into one entry per file. */
function diffFiles(diff: string): ChangedFile[] {
  return diff
    .split(/(?<=\n)(?=diff --git )/)
    .filter(part => part.startsWith('diff --git '))
    .map(diffFile)
    .filter(entry => entry.file !== '')
}

/** The untracked files, each with the hash of what it holds: the hashed paths and the hashes run in one order. */
function untrackedFiles(listing: string, hashes: string): ChangedFile[] {
  const held = hashes.split('\n')
  const hashed = hashedPaths(listing)
  return untrackedPaths(listing).map(file => ({
    file,
    status: 'added' as const,
    hunks: 0,
    diff: '',
    print: held[hashed.indexOf(file)]?.trim() ?? '',
  }))
}

/** A short print of some text: two texts with one print are taken as the same. */
export function printOf(text: string): string {
  let hash = 5381
  for (let index = 0; index < text.length; index += 1) {
    hash = ((hash << 5) + hash + text.charCodeAt(index)) | 0
  }
  return `${text.length}:${(hash >>> 0).toString(16)}`
}

/**
 * The changes of a scope, from what git printed: the diff, the listing of
 * untracked files, and the hashes of what those files hold. A path both in
 * the diff and untracked, as a file taken out of the index is, is the
 * untracked file it is on disk.
 */
export function readChanges(scope: RippleScope, base: Base, diff: string, untracked: string, hashes = ''): Changes {
  const fresh = untrackedFiles(untracked, hashes)
  const named = new Set(fresh.map(entry => entry.file))
  const files = [...diffFiles(diff).filter(entry => !named.has(entry.file)), ...fresh]
  return { scope, base, files, print: printOf([scope, diff, untracked, hashes].join('\n')) }
}

/** Each changed file's own print, by its path: what a map remembers of the changes it was made from. */
export function printsOf(changes: Changes): Record<string, string> {
  return Object.fromEntries(changes.files.map(entry => [entry.file, entry.print]))
}

/** `2 files changed on this branch since main`, `1 uncommitted file`. */
export function describeChanges(changes: Changes): string {
  const count = changes.files.length
  const files = `file${count === 1 ? '' : 's'}`
  return changes.scope === 'branch'
    ? `${count} ${files} changed on this branch since ${changes.base.name}`
    : `${count} uncommitted ${files}`
}

