// From a symbol to its code: the command that opens its file at its line in
// the person's editor.

/** The environment variables that say which terminal the session runs in and which editor the person uses. */
export type Environment = Readonly<Partial<Record<'TERM_PROGRAM' | 'VSCODE_GIT_ASKPASS_MAIN' | 'VISUAL' | 'EDITOR', string>>>

/**
 * What no path is handed on with: half a surrogate pair, and the characters
 * a Windows batch file acts on, which is what an editor's command is there.
 */
const UNSAFE = /[\p{Cs}"%&^|<>]/u

/** What follows an editor's command to open `path` at `line`; a line of 0 is none. */
type Jump = (path: string, line: number) => string[]

const goto: Jump = (path, line) => (line > 0 ? ['--goto', `${path}:${line}`] : [path])
const colon: Jump = (path, line) => [line > 0 ? `${path}:${line}` : path]
const plus: Jump = (path, line) => ['-n', ...(line > 0 ? [`+${line}`] : []), path]

/**
 * The editors Ripple starts, by the name of the command, and how each is told
 * a file and a line. Each hands the file to a window of its own and returns,
 * so nothing is left waiting on it.
 */
const EDITORS: ReadonlyMap<string, Jump> = new Map([
  ['code', goto],
  ['code-insiders', goto],
  ['cursor', goto],
  ['codium', goto],
  ['com.vscodium.codium', goto],
  ['windsurf', goto],
  ['zed', colon],
  ['subl', colon],
  ['emacsclient', plus],
])

/**
 * VS Code and its forks, each by a word the path of its own files holds and
 * by the commands it goes by. The terminal of every one of them says
 * `TERM_PROGRAM=vscode`; the path in `VSCODE_GIT_ASKPASS_MAIN` tells them
 * apart. VS Code is last, since its word is in other paths too.
 */
const VSCODE_FAMILY: ReadonlyArray<readonly [word: string, commands: readonly string[]]> = [
  ['cursor', ['cursor']],
  ['windsurf', ['windsurf']],
  ['codium', ['codium', 'com.vscodium.codium']],
  ['insiders', ['code-insiders']],
  ['code', ['code']],
]

/** The commands of the editor whose terminal the session runs in; none where it is no editor's that Ripple knows. */
function hostCommands(env: Environment): readonly string[] {
  if (env.TERM_PROGRAM === 'zed') return ['zed']
  if (env.TERM_PROGRAM !== 'vscode') return []
  const home = env.VSCODE_GIT_ASKPASS_MAIN?.toLowerCase()
  if (home === undefined) return ['code']
  return VSCODE_FAMILY.find(([word]) => home.includes(word))?.[1] ?? []
}

/** The program a `VISUAL` or `EDITOR` value starts: its first word, or what its opening quotes hold. */
function programOf(value: string | undefined): string | undefined {
  const [, double, single, bare] = /^\s*(?:"([^"]+)"|'([^']+)'|(\S+))/.exec(value ?? '') ?? []
  return double ?? single ?? bare
}

/** A program as `EDITORS` names it: no folder, no extension, lowercase. */
function nameOf(program: string): string {
  return (program.split(/[\\/]/).pop() ?? '').toLowerCase().replace(/\.(exe|cmd|bat|sh)$/, '')
}

/**
 * The commands that would open the file at `path`, an absolute path, at
 * `line`, the likeliest first: the editor whose terminal the session runs in,
 * then the one `VISUAL` names, then the one `EDITOR` names. Of those two only
 * the program is taken, so a flag that makes it wait is left behind. None
 * when the environment names no editor Ripple starts, or the path holds what
 * a command could act on.
 */
export function editorCommands(env: Environment, path: string, line: number): string[][] {
  if (UNSAFE.test(path)) return []
  const named = [programOf(env.VISUAL), programOf(env.EDITOR)].filter(program => program !== undefined)
  const commands: string[][] = []
  for (const program of new Set([...hostCommands(env), ...named])) {
    const jump = EDITORS.get(nameOf(program))
    if (jump !== undefined) commands.push([program, ...jump(path, line)])
  }
  return commands
}

files.hooks/files.ts:
import type { RippleNode, RippleReport } from '../types'

// The map by file: what both views draw. A file holds the map's symbols that
// are in it, and stands as far from the change as the files it is linked
// through put it.

/** A file of the map. */
export type MapFile = {
  path: string
  /** What the views call it: the end of its path, as much of it as tells it from the map's other files. */
  name: string
  /** `changed` when any of its symbols is, else `dependent` when any is, else `dependency`. */
  role: RippleNode['role']
  /** Files from the nearest changed one, by the links between them; 0 for a changed file. */
  depth: number
  /** The worst risk among its symbols. */
  risk: RippleNode['risk']
  /** The map's symbols in the file, by line. */
  symbols: RippleNode[]
}

/** `from` uses `to`: a symbol of the one file uses a symbol of the other. */
export type FileLink = {
  from: string
  to: string
  /** Whether a symbol of `from` that the change breaks is one that uses `to`. */
  isBreaking: boolean
}

export type FileMap = { files: MapFile[]; links: FileLink[] }

/** The roles a file takes, and the risks it is marked with, the first its symbols have of each. */
const ROLES = ['changed', 'dependent', 'dependency'] as const
const RISKS = ['breaks', 'review', 'ok'] as const

/** Each path's name: its last part, with the folders before it that it takes to be the only one so named. */
function namesOf(paths: string[]): Map<string, string> {
  const partsOf = new Map(paths.map(path => [path, path.split('/')]))
  const endOf = (path: string, count: number): string => (partsOf.get(path) ?? []).slice(-count).join('/')
  return new Map(
    paths.map(path => {
      const most = partsOf.get(path)?.length ?? 1
      let count = 1
      while (count < most && paths.some(other => other !== path && endOf(other, count) === endOf(path, count))) count += 1
      return [path, endOf(path, count)]
    }),
  )
}

/**
 * How far each file stands from the change: the changed files at 0, then,
 * role by role, the files linked to those already placed, a step at a time.
 */
function depthsOf(files: Array<Pick<MapFile, 'path' | 'role'>>, links: FileLink[]): Map<string, number> {
  const changed = files.filter(file => file.role === 'changed').map(file => file.path)
  const depths = new Map(changed.map(path => [path, 0]))
  for (const role of ['dependent', 'dependency'] as const) {
    let reached = changed
    for (let depth = 1; reached.length > 0; depth += 1) {
      const next = files
        .filter(file => file.role === role && !depths.has(file.path))
        .filter(file =>
          links.some(link =>
            role === 'dependent'
              ? link.from === file.path && reached.includes(link.to)
              : link.to === file.path && reached.includes(link.from),
          ),
        )
        .map(file => file.path)
      for (const path of next) depths.set(path, depth)
      reached = next
    }
  }
  return depths
}

/** The map by file, the files in the order the map first names them; a file no link ties to the change stands where the nearest of its symbols does. */
export function filesOf(report: RippleReport): FileMap {
  const symbolsOf = new Map<string, RippleNode[]>()
  for (const node of report.nodes) symbolsOf.set(node.file, [...(symbolsOf.get(node.file) ?? []), node])
  const byId = new Map(report.nodes.map(node => [node.id, node]))

  const links: FileLink[] = []
  for (const edge of report.edges) {
    const user = byId.get(edge.from)
    const from = user?.file
    const to = byId.get(edge.to)?.file
    if (from === undefined || to === undefined || from === to) continue
    const isBreaking = user?.risk === 'breaks'
    const link = links.find(one => one.from === from && one.to === to)
    if (link === undefined) links.push({ from, to, isBreaking })
    else link.isBreaking ||= isBreaking
  }

  const names = namesOf([...symbolsOf.keys()])
  const placed = [...symbolsOf].map(([path, symbols]) => ({
    path,
    role: ROLES.find(role => symbols.some(symbol => symbol.role === role)) ?? 'dependent',
    symbols: [...symbols].sort((a, b) => a.line - b.line),
  }))
  const depths = depthsOf(placed, links)
  const files = placed.map(file => ({
    ...file,
    name: names.get(file.path) ?? file.path,
    depth:
      depths.get(file.path) ??
      Math.min(...file.symbols.filter(symbol => symbol.role === file.role).map(symbol => symbol.depth)),
    risk: RISKS.find(risk => file.symbols.some(symbol => symbol.risk === risk)) ?? 'ok',
  }))
  return { files, links }
}

/** The file that holds symbol `id`. */
export function fileOf(map: FileMap, id: string | null): MapFile | undefined {
  return map.files.find(file => file.symbols.some(symbol => symbol.id === id))
}

/** The symbol selected when `file` is: the selected one while it is in the file, else the file's first. */
export function symbolIn(file: MapFile, selected: string | null): RippleNode | undefined {
  return file.symbols.find(symbol => symbol.id === selected) ?? file.symbols[0]
}

/** Whether `from` uses `to`. */
export function isLinked(map: FileMap, from: MapFile, to: MapFile): boolean {
  return map.links.some(link => link.from === from.path && link.to === to.path)
}

